const $=s=>document.querySelector(s);let state={step:0,clues:[],decision:null,reason:null,check:null,interest:'趋势与动量',support:'guide',revision:null};

function fox(){return `<svg class="specimen" viewBox="0 0 300 300" aria-label="几何狐狸标本" role="img"><path fill="#cf7541" d="M47 38 126 90 175 90 254 38 241 176 150 261 60 176Z"/><path fill="#85492f" d="m47 38 22 108 49-19zm207 0-22 108-49-19z"/><path fill="#f2ac67" d="m126 90 24 38 25-38 66 86-91 85-90-85z"/><path fill="#fff1d6" d="m60 176 65-23 25 108zm181 0-66-23-25 108z"/><path fill="#263e32" d="m130 219 40 0-20 20z"/><path stroke="#263e32" stroke-width="8" stroke-linecap="round" d="m97 155 18 5m70 0 18-5"/><path fill="#e68b4c" d="m126 90 24 38-25 25-65 23zm49 0-25 38 25 25 66 23z"/></svg>`}
function chart(arr=prices.slice(0,split)){let pad=Math.max((Math.max(...arr)-Math.min(...arr))*.15,.01),lo=Math.min(...arr)-pad,hi=Math.max(...arr)+pad;let points=arr.map((v,i)=>`${20+i*560/(arr.length-1)},${190-(v-lo)/(hi-lo)*155}`).join(' ');return `<svg class="chart" viewBox="0 0 600 220" role="img" aria-label="价格走势，${arr.length}个观察点"><defs><linearGradient id="shade" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#a8c77a" stop-opacity=".5"/><stop offset="1" stop-color="#a8c77a" stop-opacity="0"/></linearGradient></defs>${[45,95,145,195].map(y=>`<path d="M20 ${y}H580" stroke="#e2e7d9" stroke-dasharray="4 5"/>`).join('')}<polygon points="20,195 ${points} 580,195" fill="url(#shade)"/><polyline points="${points}" fill="none" stroke="#618745" stroke-width="3"/><text x="20" y="216" fill="#7b8873" font-size="11">T−${split-1}</text><text x="530" y="216" fill="#7b8873" font-size="11">${arr.length===split?'决策时点 T':'T+'+(arr.length-split)}</text></svg>`}
function render(html){$('#app').innerHTML=html;window.scrollTo(0,0);if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches)$('#app').animate([{opacity:0,transform:'translateY(8px)'},{opacity:1,transform:'translateY(0)'}],{duration:300,easing:'ease-out'});}
function fresh(){return {step:1,clues:[],decision:null,interest:'趋势与动量',support:'guide',revision:null,storm:[],round:0,tools:{},selected:null,hints:[],attempts:0,repairs:[],log:[],feedback:''}}
function home(){render(`<section class="expedition-cover"><div class="cover-copy"><span class="eyebrow">PANDA / THE UNKNOWN EXPEDITION</span><h1>交易物种<br><em>迷雾远征</em></h1><p class="lead">带上两枚调查币，穿过未知行情。<br>在反转中做决定，把失灵的策略修好。<br>你是什么探索者？玩过才知道。</p><div class="actions"><button class="primary" onclick="start()">领取背包 · 出发 →</button><button class="secondary" onclick="judge()">看看不同玩家的路线</button></div><p class="micro">约 4 分钟 · 无需登录 · 无真实交易 · 不按收益排名</p></div><div class="island"><div class="island-orbit"></div><span class="island-label l1">01 迷雾岔路</span><span class="island-label l2">02 反转风暴</span><span class="island-label l3">03 策略修理铺</span>${fox()}<span class="island-caption">你的物种，尚未发现</span></div></section><div class="data-ribbon"><span>● ${dataLabel}</span><span>${realData?escapeHTML(dataset.symbol)+' · '+rows.length+' 个交易日':'合成行情演示 · 本机支持授权数据'}</span></div>${filmTeaser()}<section class="strip"><div><b>调查，要做取舍</b><p>三份情报，两枚硬币。信息不会自动送到你面前。</p></div><div><b>未来，逐段打开</b><p>每一次行动都会留下轨迹。看完结果还能改变主意。</p></div><div><b>修好，再开新地图</b><p>亲手组装验证工具。你的下一站由表现和偏好共同决定。</p></div></section><section class="purpose"><span class="eyebrow">PLAY → EVIDENCE → YOUR NEXT MAP</span><h2>解决“进了研究平台，却不知道从哪里开始”。</h2><p>把第一次接触变成探索：观察你的信息选择、调整过程与验证操作，再匹配带练工坊或开放研究营地。物种只是纪念，下一步才是目的。</p><button class="demo" onclick="showMethod()">查看判断规则与局限 →</button></section>`)}
function start(){state=fresh();game()}
function stageHeader(n,title){return `<div class="pagehead"><div><span class="eyebrow">EXPEDITION / 第 ${n} 站</span><h1>${title}</h1></div><button class="demo" onclick="home()">返回营地</button></div><div class="map-track">${['迷雾岔路','反转风暴','策略修理铺'].map((x,i)=>`<span class="${i+1===n?'active':i+1<n?'done':''}">${i+1<n?'✓':i+1} ${x}</span>`).join('')}</div>`}
function game(){if(state.step===1)fog();else if(state.step===2)storm();else workshop()}
const clues={volume:['量能望远镜','🔭',()=>volumeClue()],sample:['档案罗盘','🧭',()=> '缺少独立的相似历史样本。这条走势不能提供可靠胜率。'],story:['热帖收音机','📻',()=> '模拟广播：“这次突破一定会涨！”没有样本、失败记录或成本说明。']};
function fog(){render(stageHeader(1,'雾里出现了一条岔路。')+`<div class="gamegrid"><section class="panel terrain"><div class="row"><span class="tag">${dataLabel}</span><b>调查币 ${'●'.repeat(2-state.clues.length)}${'○'.repeat(state.clues.length)}</b></div>${chart()}<h2>${evidenceHeadline()}</h2><p>山路通往未知行情。你可以调查两份情报，也可以现在出发。</p><div class="clue-deck">${Object.entries(clues).map(([k,v])=>`<button class="clue-card ${state.clues.includes(k)?'opened':''}" onclick="clue('${k}')" ${state.clues.length===2&&!state.clues.includes(k)?'disabled':''}><span>${v[1]}</span><b>${v[0]}</b><small>${state.clues.includes(k)?v[2]():'花 1 枚币 · 翻开情报'}</small></button>`).join('')}</div><div class="notice">只显示截至 ${escapeHTML(rows[split-1].date)} 的行情。线索预算相同；没看某条线索不代表不会。</div></section><aside class="panel"><span class="eyebrow">CHOOSE YOUR TRAIL</span><h2>第一步，走哪条路？</h2><div class="options"><button class="option" onclick="decide('act')"><strong>🥾 轻装试探 →</strong><small>带一份模拟仓位前进，体验价格变化。</small></button><button class="option" onclick="decide('wait')"><strong>⛺ 留在观察点 →</strong><small>先空仓观察，下一段仍可出发。</small></button><button class="option" onclick="decide('detour')"><strong>🧭 绕路考察 →</strong><small>先标记证据缺口，下一段补查数据。</small></button></div><div class="info">没有最佳路线。我们记录你的研究方式，收益不会决定物种或能力。</div></aside></div>`)}
function clue(k){if(!clues[k]||state.clues.includes(k)||state.clues.length>=2)return;state.clues.push(k);state.log.push({event:'investigate',key:k,visibleEnd:rows[split-1].date});fog()}
function decide(k){state.decision=k;state.position=k==='act'?1:0;state.step=2;state.log.push({event:'first_move',action:k,visibleEnd:rows[split-1].date});storm()}
function revealEnd(round=state.round){return Math.min(rows.length,split+Math.ceil((rows.length-split)*(round+1)/2))}
function storm(){let end=revealEnd(),prior=state.round?revealEnd(0):split,change=(prices[end-1]/prices[prior-1]-1)*100;render(stageHeader(2,'风向变了。你的计划呢？')+`<div class="gamegrid"><section class="panel terrain"><div class="row"><span class="tag">第 ${state.round+1} / 2 阵风 · ${escapeHTML(rows[end-1].date)}</span><span>当前：${state.position?'轻仓试探':'空仓观察'}</span></div>${chart(prices.slice(0,end))}<div class="wind-report" role="status"><span>${change>=0?'↗':'↘'}</span><div><b>新揭晓区间 ${change>=0?'+':''}${change.toFixed(2)}%</b><p>${state.position?'你带着模拟仓位经历了这一段波动。':'你在观察点看见了这一段波动。'}价格揭晓用于观察反应，不计算能力分。</p></div></div>${state.decision==='detour'?'<div class="info">绕路笔记：已标记样本不足。补查时优先核对数据口径，而不是继续找支持上涨的说法。</div>':''}${state.auditNote?`<div class="info">🔎 ${escapeHTML(state.auditNote)}</div>`:''}<p>背包里的情报：${state.clues.map(k=>clues[k][0]).join('、')||'未使用调查币'}</p><div class="notice">${end<rows.length?'剩余行情仍未揭晓。':'本段已全部揭晓；此后的重复实验不再是未见样本。'}这里展示收盘变化，不作为可成交回测。</div></section><aside class="panel"><h2>做一次真实取舍</h2><div class="options">${[['hold','🪨 保持原计划','保留当前仓位，观察下一段变化。'],['switch','🔀 调整路线',state.position?'撤回观察点，下一段空仓。':'带一份模拟仓位，进入下一段。'],['inspect','🔎 停下来复核','暂停参与，核对样本与数据口径。']].map(([k,t,d])=>`<button class="option" onclick="stormMove('${k}')"><strong>${t}</strong><small>${d}</small></button>`).join('')}</div><p class="muted">改变或不改变都不加分。后续档案会展示你的完整轨迹。</p></aside></div>`)}
function stormMove(action){let end=revealEnd();state.storm.push({action,visibleEnd:rows[end-1].date,positionBefore:state.position});state.log.push({event:'storm_move',...state.storm.at(-1)});if(action==='switch')state.position=1-state.position;if(action==='inspect'){state.position=0;state.auditNote='复核发现：当前仅 '+rows.length+' 条观察点，复权口径'+dataset.adjustment+'；单段走势不能给出可靠胜率。';}if(state.round++===0)storm();else {state.step=3;workshop()}}
const toolset={clock:['⏱','时间闸','让信号先发生，成交后发生'],vault:['🔐','封存箱','把没用于调参的数据留给检验'],cost:['🧮','成本表','扣掉每次交易的摩擦费用']};
const machines=[['timing','01 / 信号引擎','用当天收盘价发出信号，却按当天开盘价买入。','clock'],['sample','02 / 参数齿轮','在同一段数据调 50 次参数，再用它宣布有效。','vault'],['fees','03 / 收益仪表','频繁换仓，报告只累加价格涨幅。','cost']];
function workshop(){render(stageHeader(3,'漂亮的策略机器，为什么冒烟？')+`<section class="panel workshop"><div class="row"><div><span class="tag">动手关卡 · 三件工具，各用一次</span><h2>选一件工具，再点一个故障槽位。</h2></div><span class="repair-count">${state.repairs.length} / 3 已修复</span></div>${state.auditNote?`<div class="info">风暴复核笔记：${escapeHTML(state.auditNote)}</div>`:''}<p>研究员拿来一台“收益很漂亮”的机器。先修复验证流程，它才有资格接受检验。</p><div class="tool-belt">${Object.entries(toolset).map(([k,v])=>`<button class="tool ${state.selected===k?'selected':''}" onclick="selectTool('${k}')" aria-pressed="${state.selected===k}"><span>${v[0]}</span><b>${v[1]}</b><small>${v[2]}</small></button>`).join('')}</div><div class="machine-line">${machines.map(([k,t,d,correct])=>`<button class="machine ${state.repairs.includes(k)?'fixed':''}" onclick="installTool('${k}')"><small>${t}</small><span class="gear">${state.repairs.includes(k)?'✦':'⚙'}</span><b>${d}</b><span class="socket">${state.tools[k]?toolset[state.tools[k]][0]+' '+toolset[state.tools[k]][1]:'＋ 点击安装选中工具'}</span></button>`).join('')}</div><div class="row actions"><button class="primary" onclick="testMachine()" ${Object.keys(state.tools).length<3?'disabled':''}>启动诊断 →</button><button class="secondary" onclick="repairHint()">请搭档提示</button><span class="muted">诊断 ${state.attempts} 次 · 提示 ${state.hints.length} 次</span></div><div role="status" class="info">${state.feedback||'工具可以移动、替换。装错不会扣分；我们区分首次独立完成与得到反馈后的完成。'}</div>${state.repairs.length===3?`<div class="repair-success"><h2>机器恢复了。你的物种也浮现了。</h2><p>修好流程不意味着策略盈利，意味着现在可以认真检验它。</p><label for="support">下一站想怎样探索？</label><select id="support" onchange="state.support=this.value"><option value="guide" ${state.support==='guide'?'selected':''}>有搭档带路</option><option value="independent" ${state.support==='independent'?'selected':''}>自主探索</option></select><button class="primary" onclick="result()">揭晓物种 · 展开新地图 →</button></div>`:''}</section>`)}
function selectTool(k){state.selected=k;workshop()}
function installTool(slot){if(!state.selected){state.feedback='先点击上面的工具，再选择要修理的位置。';workshop();return}for(let k in state.tools)if(state.tools[k]===state.selected)delete state.tools[k];state.tools[slot]=state.selected;state.repairs=[];state.feedback='工具已装入。填满三个槽位后启动诊断。';state.selected=null;workshop()}
function testMachine(){state.attempts++;state.repairs=machines.filter(m=>state.tools[m[0]]===m[3]).map(m=>m[0]);state.log.push({event:'repair_test',attempt:state.attempts,tools:{...state.tools},correct:state.repairs.length,hints:state.hints.length});state.feedback=state.repairs.length===3?'✓ 时间顺序、独立样本与交易成本均已修复。':`已修复 ${state.repairs.length} 处。${machines.filter(m=>!state.repairs.includes(m[0])).map(m=>m[1]+'仍异常').join('；')}。试着把工具重新组合。`;workshop()}
function repairHint(){state.hints.push('mapping');state.feedback='搭档提示：信号引擎要检查先后时间；参数齿轮要隔离未见样本；收益仪表要补上交易费用。提示后的成功会作为学习表现记录。';workshop()}
function profile(s=state){let independent=s.log.some(x=>x.event==='repair_test'&&x.attempt===1&&x.correct===3&&x.hints===0),checked=s.storm.some(x=>x.action==='inspect'),verified=s.repairs.length===3;let evidence=s.clues.includes('sample')&&checked;let species=evidence&&verified?'证据狐狸':s.decision==='act'&&s.storm.some(x=>x.action==='hold')?'信号猎豹':s.decision!=='act'&&s.storm.some(x=>x.action==='hold')?'耐心大象':'迁徙候鸟';let route=independent?(s.support==='independent'?'independent':'validation'):'guided';return {version:'3.0',species,route,verified,independent,conflict:s.clues.includes('sample')&&!independent,confidence:evidence&&independent?'中等':'有限',revision:s.revision,interest:s.interest,support:s.support,source:dataset.source,dataset:{symbol:dataset.symbol,rows:rows.length,split,adjustment:dataset.adjustment},evidence:s.log,unknown:['真实风险承受力未测','编程能力未测','行为跨情境稳定性未测'],taskState:s.revision?'completed':'not_started'}}
const tasks={guided:['假设工坊：跟搭档修好一个研究想法','带练地图 · 步骤解释与反馈'],validation:['验证山谷：封存规则，检查新证据','验证地图 · 引导式实验'],independent:['开放营地：建立你的研究记录','自主地图 · 参数与数据导出']};
function result(){let p=profile();render(`<div class="pagehead"><div><span class="eyebrow">EXPEDITION COMPLETE / 新物种发现</span><h1>你走过的路，变成了下一张地图。</h1></div><button class="demo" onclick="revisit()">改变第一步，重走分支 ↺</button></div><section class="result"><div class="passport"><span class="eyebrow">本次探索的趣味化身</span>${p.species==='证据狐狸'?fox():`<div class="species-emoji">${p.species==='信号猎豹'?'🐆':p.species==='耐心大象'?'🐘':'🕊️'}</div>`}<h1>${p.species}</h1><p>${p.species==='迁徙候鸟'?'你在变化中调整路线，愿意改变探索方式。':'你的调查、行动和修理记录，共同留下了这个轮廓。'}</p><div class="notice">证据充分度：${p.confidence}。不是心理人格或投资能力等级。</div></div><div class="panel"><h2>物种不是猜的，轨迹可以回看。</h2><div class="evidence"><b>迷雾 · ${state.clues.map(k=>clues[k][0]).join(' + ')||'直接出发'}</b><p>首选${{act:'轻装试探',wait:'观察点',detour:'绕路考察'}[state.decision]}。预算约束下的信息偏好，不是能力分。</p></div><div class="evidence"><b>风暴 · ${state.storm.map(x=>({hold:'保持',switch:'调整',inspect:'复核'})[x.action]).join(' → ')}</b><p>行动与当时可见时间一并保留，不用事后涨跌评判决定。</p></div><div class="evidence"><b>修理 · ${p.independent?'首次独立修复三处':'在反馈或提示后完成'}</b><p>${state.attempts} 次诊断，${state.hints.length} 次提示。${p.independent?'本次展示验证知识；尚不代表跨情境能力。':'这是学习过程的证据，不推断你能力低。'}</p></div>${p.conflict?'<div class="info">观察到你主动查样本；修理过程仍需要反馈。两条记录同时保留，先提供可跳转的带练地图。</div>':''}<p class="notice">仍未知：编程水平、真实风险承受力与长期行为。刷新清空本次记录。</p></div></section><section class="task next-map"><span class="tag">已解锁下一张地图</span><h2>${tasks[p.route][0]}</h2><p>${p.independent?'你独立完成验证流程修复；结合你选择的探索方式，开放对应实验。':'你完成了修复；先用可解释的实验巩固验证步骤，也可以自行切换研究方式。'}</p><label for="route-support">探索方式可修改</label><select id="route-support" onchange="state.support=this.value;result()"><option value="guide" ${state.support==='guide'?'selected':''}>搭档带路</option><option value="independent" ${state.support==='independent'?'selected':''}>自主探索偏好</option></select><div class="actions"><button class="primary" onclick="lab()">进入推荐地图 →</button><button class="secondary" onclick="state.support='independent';lab()">我想直接做实验</button></div></section><div class="actions"><button class="secondary" onclick="downloadProfile()">导出行为档案</button><button class="secondary" onclick="shareCard()">带走物种卡</button><button class="demo" onclick="showMethod()">规则与局限</button></div>${state.previous?`<div class="info">分支对比：上次 ${state.previous.species} / ${tasks[state.previous.route][0]} → 本次 ${p.species} / ${tasks[p.route][0]}。变化由调查、风暴反应与修理表现共同决定；只改变第一步不必改变推荐。</div>`:''}`)}
function revisit(){let previous=profile();state=fresh();state.previous={species:previous.species,route:previous.route};game()}
function demo(k){state=fresh();state.clues=k==='expert'?['volume','sample']:['story'];state.decision='wait';state.storm=[{action:'hold'},{action:'inspect'}];state.repairs=['timing','sample','fees'];state.attempts=k==='expert'?1:2;state.hints=k==='expert'?[]:['mapping'];state.log=[{event:'simulated_path',label:k},{event:'repair_test',attempt:state.attempts,correct:3,hints:state.hints.length}];state.support=k==='expert'?'independent':'guide';result()}
let locked=false,labWindow=3,labResult=null,visitedHoldout=false;
function lab(){visitedHoldout=state.storm.length>0;locked=false;labWindow=3;labResult=null;drawLab()}
function sourceNote(){return realData?`来自授权 Panda Data 接口，${escapeHTML(dataset.symbol)}，${escapeHTML(rows[0].date)}—${escapeHTML(rows.at(-1).date)}。共 ${rows.length} 条；复权口径${escapeHTML(dataset.adjustment)}。样本较短，仅用于入门实验，不代表策略验证完成。`:'40 点固定合成序列用于演示，不是真实市场表现。本机版可以使用已授权的 Panda Data 样本。'}
function drawLab(){let p=profile(),risk=state.interest==='风险与回撤',quality=state.interest==='数据质量';render(`<div class="pagehead"><div><div class="eyebrow">FIRST RESEARCH / ${tasks[p.route][1]}</div><h1>${quality?'先验证数据，再验证想法。':risk?'好策略，也要经得起回撤。':'让一个交易直觉，接受一次检验。'}</h1></div><button class="demo" onclick="result()">返回档案</button></div><div class="journey"><span class="done">✓ 认识研究习惯</span><span class="active">02 完成一次实验</span><span>03 获得下一步</span></div><div class="gamegrid"><section class="panel"><div class="row"><span class="tag">${dataLabel}</span><span class="muted">${locked?'检验区间已揭晓':'未来区间暂未展示'}</span></div>${chart(locked?prices:prices.slice(0,split))}<h2>${quality?'假设：这组价格可以直接用于研究':risk?'假设：趋势过滤会降低持有过程中的回撤':'假设：高于近期均价时持有，能优于始终持有'}</h2>${p.route==='guided'?'<div class="coach"><b>你的研究搭档</b><p>先写下规则，再看结果。这里没有“最优参数”提示——我们希望你学会检验一个想法，而不是猜中答案。</p></div>':''}${quality?'<p>本次检查缺失值、非正价格和重复日期。通过检查也不能证明数据口径、停牌与复权处理都正确。</p>':`<label for="window">回看窗口 <b>${labWindow}</b> 个观察点</label><input id="window" type="range" min="2" max="8" value="${labWindow}" ${locked?'disabled':''} onchange="labWindow=Number(this.value);drawLab()"><div class="info">用前一日收盘价与更早的 ${labWindow} 日均价比较，高于均价则在下一日开盘持有，否则空仓。手续费按仓位变化收取 0.1%，样本最后一个开盘时点平仓。</div>`}<p class="muted">${visitedHoldout?'你已经看过此检验区间。再次实验属于重复探索，不能当作新的独立验证。':'参数封存之前，不展示检验结果。'}${p.route==='independent'?' 你可以导出数据自行复核。':''}</p><button class="primary" onclick="runLab()" ${locked?'disabled':''}>${locked?'已完成计算 ✓':quality?'开始数据体检 →':'封存规则，打开检验区间 →'}</button><div id="labresult">${locked?labOutput():''}</div></section><aside class="panel"><span class="eyebrow">YOUR EXPERIMENT CARD</span><h2>这不是一次收益比赛</h2><div class="evidence"><strong>① 探索区间 · ${split} 点</strong><p>${escapeHTML(rows[0].date)} → ${escapeHTML(rows[split-1].date)}</p></div><div class="evidence"><strong>② 检验区间 · ${rows.length-split} 点</strong><p>${escapeHTML(rows[split].date)} → ${escapeHTML(rows.at(-1).date)}<br>开盘到次日开盘共 ${rows.length-split-1} 段收益。</p></div><div class="evidence"><strong>③ 判断结果的边界</strong><p>盈亏不进入能力评分。我们更关心你是否理解样本、成本和可推广性。</p></div><div class="notice">${sourceNote()}<br>只模拟日频开盘成交，未模拟涨跌停、滑点与成交限制；回撤仅按日频净值估算。</div>${p.route==='independent'?'<button class="secondary" style="margin-top:20px" onclick="exportData()">导出数据 CSV</button>':''}<details><summary>数据与推荐资源</summary><p><a href="https://www.pandaaiquant.com/docs/data" target="_blank" rel="noopener">Panda Data 接入说明 ↗</a></p><p><a href="https://github.com/quantskills/skill-pandadata-api" target="_blank" rel="noopener">QuantSkills · PandaData API 资源 ↗</a>：适合自主探索者查接口与字段。当前为资源推荐，没有安装或执行该 Skill。</p></details></aside></div>`)}
function labOutput(){const r=labResult,q=qualityReport(),quality=state.interest==='数据质量',risk=state.interest==='风险与回撤';if(!r)return '';return `<div class="experiment-result"><span class="eyebrow">OBSERVATION / 结果不等于结论</span><div class="stats">${quality?`<div class="stat"><b>${q.count}</b><span>观察点</span></div><div class="stat"><b>${q.missing+q.invalid}</b><span>缺失 / 无效行</span></div><div class="stat"><b>${q.duplicates}</b><span>重复日期</span></div>`:`<div class="stat"><b>${(risk?r.dd:r.ret).toFixed(2)}%</b><span>${risk?'策略最大回撤':'策略净收益'}</span></div><div class="stat"><b>${(risk?r.baseDD:r.baseReturn).toFixed(2)}%</b><span>${risk?'持有最大回撤':'持有净收益'}</span></div><div class="stat"><b>${r.trades}</b><span>仓位变化次数</span></div>`}</div><p>${quality?'基础检查只能发现部分问题。复权、停牌、可成交性和数据授权仍需单独核对。':risk?`本样本中趋势过滤${r.dd<r.baseDD?'降低了':'没有降低'}日频最大回撤。仅 ${r.periods} 段收益，无法证明这种结果稳定。`:`本样本中策略${r.ret>r.baseReturn?'优于':'未超过'}同口径持有基准。两者均计入成本，不因一次正收益判定策略有效。`}</p><h3>你会怎样写下这次结论？</h3><div class="options"><button class="option" onclick="revise(true)"><strong>先保留结论，补充独立证据</strong><small>换市场阶段、扩大样本，并检查数据与成交假设</small></button><button class="option" onclick="revise(false)"><strong>结果已经证明长期可靠</strong><small>直接推广到其他市场和未来情境</small></button></div></div>`}
function runLab(){locked=true;visitedHoldout=true;labResult=compute(labWindow);drawLab()}
function revise(ok){state.revision={task:state.interest,correct:ok,note:ok?'完成实验后能主动保留结论，识别样本局限':'完成实验后仍将单次结果泛化，需要进一步认识验证边界',experiment:{window:labWindow,source:dataset.source,observations:rows.length,return:labResult.ret,drawdown:labResult.dd},next:ok?'跨阶段验证':'样本偏差带练'};completion()}
function completion(){const p=profile(),r=state.revision;render(`<div class="completion-hero"><span class="seal">✓</span><span class="eyebrow">FIRST RESEARCH COMPLETED</span><h1>你完成了第一份研究记录。</h1><p>从“我会怎么选”，到“我该怎样验证”。<br>比拿到一种标签，更重要的是开始行动。</p><div class="journey"><span class="done">✓ 游戏</span><span class="done">✓ 画像</span><span class="done">✓ 实验</span></div></div><section class="result"><div class="panel"><span class="eyebrow">PROFILE UPDATE / 01</span><h2>新证据，已经回到你的档案</h2><div class="evidence"><b>原探索</b><p>${p.verified?'完成了验证流程修复。':'尚未在修理中展示独立验证操作。'}</p></div><div class="evidence"><b>这次任务</b><p>${r.note}。</p></div><div class="info">${!p.verified&&r.correct?'新的表现与你原来的修理表现不同：这可能是学习进展，也可能是提示效应。我们保留两条记录，不急着提升能力等级。':r.correct?'这条证据支持你的验证意识，但仍不足以推断跨情境能力。':'单次结果不能证明未来可靠。下一步继续提供带练，而不是提升能力标签。'}</div></div><div class="task" style="margin-top:0"><span class="tag">根据新证据调整的下一步</span><h2>${r.next}</h2><p>${r.correct?'先把这次规则固定下来，再寻找一个未看过的市场阶段。比较收益、回撤与成本敏感性，记录哪些结论改变了。':'先理解为什么“见过的数据”容易让结论显得更好。完成下面的两例对比，再决定如何验证。'}</p><button class="primary" onclick="nextLesson()">开始下一步 →</button></div></section><div class="actions"><button class="secondary" onclick="downloadProfile()">下载研究档案 JSON</button><button class="secondary" onclick="shareCard()">带走我的物种卡</button><button class="demo" onclick="result()">查看更新后的画像</button><button class="demo" onclick="home()">回到研究所</button></div>`)}
function nextLesson(){let advanced=state.revision.correct;render(`<div class="pagehead"><div><span class="eyebrow">NEXT EXPLORATION / ${advanced?'跨阶段验证':'样本偏差带练'}</span><h1>${advanced?'怎样找到真正的新证据？':'哪个结果，更值得继续研究？'}</h1></div><button class="demo" onclick="completion()">返回研究记录</button></div><section class="panel"><p>${advanced?'你已经看过当前区间的走势，并调整过规则。现在想判断规则是否能推广。':'研究员 A 在同一段数据上试了 100 次，挑出收益最高的一次。研究员 B 先固定规则，再看一段从未参与调参的数据。'}</p><div class="options"><button class="option" onclick="lessonAnswer(false)">${advanced?'继续在当前区间调整到最高收益，再把它叫作验证':'A 的收益更高，所以 A 的方法更可靠'}</button><button class="option" onclick="lessonAnswer(true)">${advanced?'记录固定规则，在此前未参与决策的区间检查':'B 的方法更适合检验泛化，但仍要考虑样本数量与成本'}</button></div><div id="lesson-feedback" role="status"></div></section>`)}
function lessonAnswer(ok){$('#lesson-feedback').innerHTML=`<div class="info">${ok?'✓ 正确。关键是让验证数据不参与规则选择，并且保留失败结果。':'还需要区分“挑出最好结果”和“检验已固定的规则”。前者可能只是适配了已知样本。'}</div><button class="secondary" style="margin-top:16px" onclick="completion()">返回研究记录</button>`}
function judge(){render(`<div class="pagehead"><h1>同样留在观察点，下一站可以不同。</h1><button class="demo" onclick="home()">回到营地</button></div><p class="notice">以下是两条预设模拟路径，不是真实用户实验。</p><div class="compare-grid"><section class="panel"><h2>A · 边玩边学</h2><p>收听热帖 → 观察 → 保持 → 复核 → 提示后修好机器。</p><h3>解锁：假设工坊</h3><p>提供步骤解释，继续观察学习表现。</p><button class="primary" onclick="demo('beginner')">展开 A 的地图 →</button></section><section class="panel"><h2>B · 独立核验</h2><p>查量能与样本 → 观察 → 保持 → 复核 → 首次独立修复。</p><h3>解锁：开放营地</h3><p>结合自主偏好，开放参数实验与数据导出。</p><button class="primary" onclick="demo('expert')">展开 B 的地图 →</button></section></div>`)}

function save(name,data,type){let u=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function downloadProfile(){save('panda-research-profile.json',JSON.stringify(profile(),null,2),'application/json')}
function exportData(){save('research-data.csv','date,open,close,volume,split,source\n'+rows.map((r,i)=>`${r.date},${r.open},${r.close},${r.volume},${i<split?'exploration':'holdout'},${dataset.source}`).join('\n'),'text/csv')}
function shareCard(){let p=profile();save('my-species.svg',`<svg xmlns="http://www.w3.org/2000/svg" width="720" height="900"><rect width="720" height="900" rx="30" fill="#263e32"/><text x="60" y="95" fill="#bdeb65" font-size="22">PANDA / FIELD LAB</text><text x="60" y="350" fill="#f4f3eb" font-size="68">${p.species}</text><text x="60" y="440" fill="#c1cdbd" font-size="25">每一种探索，都有方向。</text><text x="60" y="740" fill="#c1cdbd" font-size="19">趣味物种卡 · 不代表固定人格或投资能力</text><text x="60" y="785" fill="#bdeb65" font-size="18">分享卡不包含原始行为记录</text></svg>`,'image/svg+xml')}
function showMethod(){render(`<div class="pagehead"><h1>每个判断，都能找到来处。</h1><button class="secondary" onclick="home()">返回营地</button></div><section class="panel"><h2>解决的问题</h2><p>首次进入量化平台的用户不知道从哪开始。调查、动态选择和工具修复提供行为线索，再匹配第一次研究任务。</p><h2>规则公开</h2><p>查样本、风暴复核并完成修理，形成证据狐狸；试探且曾保持，形成信号猎豹；观察或绕路且曾保持，形成耐心大象；其他轨迹为迁徙候鸟。物种是可修改的行为比喻，不是能力排名。</p><p>首次无提示完整修复，只提供本次验证知识的证据；结合自主偏好推荐开放营地，否则推荐验证山谷。提示或反馈后完成推荐假设工坊，不据此认定能力低。查样本、复核与独立修复三条一致时证据充分度为中等，否则有限；这不是统计置信度。</p><h2>真实数据怎样进入游戏</h2><p>${sourceNote()}前 ${split} 点可见，之后分两段揭晓；每次决策记录可见截止时间。再做实验时，已经看过的区间不可声称独立未见样本。修理铺是明确标注的教学故障，不伪称真实策略表现。</p><h2>资源与边界</h2><p>Panda Data 授权数据只在本机使用，线上为合成样本。QuantSkills 的 PandaData API 是推荐资源，未安装或执行。收益不用于能力判断。没有真实用户验证、心理测量或转化率结论。行为只在页面内存中保存，可主动导出。</p><p><a href="https://www.pandaaiquant.com/docs/data" target="_blank" rel="noopener">Panda Data 说明</a> · <a href="https://github.com/quantskills/skill-pandadata-api" target="_blank" rel="noopener">QuantSkills 资源</a></p></section>`)}
let filmTimer=null,filmFrame=0,filmRunning=false,filmReturn=null;
const filmChapters=[['01 / THE SIGNAL','市场每天，都在发出信号。','面对同一段行情，每个人看见的线索并不相同。'],['02 / THE EVIDENCE','先看什么，透露你的研究习惯。','价格、量能、样本。你会把有限的注意力放在哪里？'],['03 / YOUR SPECIES','你的物种，藏在选择背后。','行动不代表专业，观望也不一定保守。我们会继续追问。'],['04 / THE NEXT STEP','认识自己，然后开始一次研究。','一份有依据的档案，带你走向适合自己的下一步。']];
function introArt(){return `<svg viewBox="0 0 800 430" class="film-art" aria-hidden="true"><defs><linearGradient id="forest" x2="0" y2="1"><stop stop-color="#1f4537"/><stop offset="1" stop-color="#102c24"/></linearGradient></defs><rect width="800" height="430" fill="url(#forest)"/><circle cx="605" cy="110" r="66" fill="#d6e8a5" opacity=".8"/><g class="film-stars" fill="#c6ed89"><circle cx="100" cy="70" r="3"/><circle cx="220" cy="120" r="2"/><circle cx="350" cy="45" r="3"/><circle cx="710" cy="170" r="3"/><circle cx="490" cy="80" r="2"/></g><g opacity=".5" fill="#4f7853"><path d="M0 330 95 100 190 330Z"/><path d="M100 360 235 135 340 360Z"/><path d="M540 360 665 110 790 360Z"/></g><g class="film-candles" stroke-width="2">${[130,160,140,190,220,180,245,270,235,290,305,280].map((v,i)=>`<g stroke="${i%3?'#c3ea7e':'#dc9966'}" fill="${i%3?'#c3ea7e':'#dc9966'}"><path d="M${95+i*51} ${380-v-16}v70"/><rect x="${85+i*51}" y="${380-v}" width="20" height="34" rx="3"/></g>`).join('')}</g><path class="film-trail" d="M70 310 160 290 220 310 290 255 350 270 425 210 490 225 550 170 640 190 730 130" fill="none" stroke="#c5ed80" stroke-width="3"/><path d="M0 390Q160 325 320 385T800 350V430H0Z" fill="#102a23"/><g class="film-fox" transform="translate(310 125) scale(.7)"><path fill="#ce7743" d="M47 38 126 90 175 90 254 38 241 176 150 261 60 176Z"/><path fill="#85492f" d="m47 38 22 108 49-19zm207 0-22 108-49-19z"/><path fill="#f2ac67" d="m126 90 24 38 25-38 66 86-91 85-90-85z"/><path fill="#fff1d6" d="m60 176 65-23 25 108zm181 0-66-23-25 108z"/><path fill="#263e32" d="m130 219 40 0-20 20z"/><path stroke="#263e32" stroke-width="8" stroke-linecap="round" d="m97 155 18 5m70 0 18-5"/></g><g class="film-clues" fill="#f5f4e9"><rect x="120" y="120" width="145" height="65" rx="8"/><rect x="535" y="230" width="145" height="65" rx="8"/><text x="142" y="160" fill="#284333" font-size="20">样本够多吗？</text><text x="557" y="270" fill="#284333" font-size="20">结论可靠吗？</text></g><g class="film-orbit" fill="none" stroke="#bde77b" opacity=".5"><circle cx="415" cy="235" r="125" stroke-dasharray="4 10"/></g></svg>`}
function filmTeaser(){return `<button class="film-teaser" onclick="openIntro()" aria-label="播放 20 秒市场丛林开场动画"><span class="teaser-play">▶</span><span><b>20 秒，走进市场丛林</b><small>四幕动画 · 静音播放 · 随时跳过</small></span><span class="teaser-wave">▁ ▃ ▆ ▂ ▅ ▇ ▄</span></button>`}
function openIntro(){filmReturn=document.activeElement;filmFrame=0;filmRunning=false;let modal=document.getElementById('intro-film');if(!modal){modal=document.createElement('dialog');modal.id='intro-film';modal.setAttribute('aria-label','市场丛林开场动画');modal.innerHTML=`<div class="film-top"><span>PANDA / A FIELD EXPEDITION</span><button onclick="closeIntro()" aria-label="关闭动画">关闭 ×</button></div><div id="film-scene" class="film-scene stage-0 paused">${introArt()}<span class="film-watermark">概念动画 · 非真实行情</span><div class="film-caption"><span id="film-kicker"></span><h2 id="film-title"></h2><p id="film-desc"></p></div></div><div class="film-controls"><button id="film-toggle" onclick="toggleIntro()">播放</button><span id="film-clock">00:00 / 00:20</span><input aria-label="动画播放进度" id="film-seek" type="range" min="0" max="200" value="0" oninput="seekIntro(this.value)"><button onclick="replayIntro()">重播</button><button class="film-start" onclick="closeIntro();start()">跳过，开始探索 →</button></div>`;modal.addEventListener('close',stopIntro);document.body.append(modal)}modal.showModal();updateIntro();if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches)toggleIntro()}
function updateIntro(){const chapter=Math.min(3,Math.floor(filmFrame/50)),copy=filmChapters[chapter],scene=$('#film-scene');scene.className=`film-scene stage-${chapter} ${filmRunning?'':'paused'}`;$('#film-kicker').textContent=copy[0];$('#film-title').textContent=copy[1];$('#film-desc').textContent=copy[2];$('#film-clock').textContent=`00:${String(Math.floor(filmFrame/10)).padStart(2,'0')} / 00:20`;$('#film-seek').value=filmFrame;$('#film-toggle').textContent=filmRunning?'暂停':'播放';if(filmFrame>=200){stopIntro();$('#film-toggle').textContent='播放';scene.classList.add('paused')}}
function stopIntro(){clearInterval(filmTimer);filmTimer=null;filmRunning=false;const scene=$('#film-scene');if(scene)scene.classList.add('paused')}
function toggleIntro(){if(filmRunning){stopIntro();updateIntro();return}if(filmFrame>=200)filmFrame=0;filmRunning=true;let last=performance.now();filmTimer=setInterval(()=>{let now=performance.now();filmFrame=Math.min(200,filmFrame+(now-last)/100);last=now;updateIntro()},100);updateIntro()}
function seekIntro(value){filmFrame=Number(value);updateIntro()}
function replayIntro(){stopIntro();filmFrame=0;toggleIntro()}
function closeIntro(){stopIntro();document.getElementById('intro-film').close();filmReturn?.focus()}

home();

